import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { vec2, uv, texture, time, mix, sin, mul, add } from 'three/tsl';

const createNode = (config, ctx) => {
  // Extract scene placement
  const pos = config.scenePosition || { x: 0, y: 0, z: 0, rotX: 0, rotY: 0, rotZ: 0, scaleX: 1, scaleY: 1, scaleZ: 1 };
  const { x, y, z, rotX, rotY, rotZ, scaleX, scaleY, scaleZ } = pos;

  // Source rect aspect ratio (512x320)
  const aspect = 512 / 320;
  const width = 1.6;  // Approximate card width in scene units
  const height = width / aspect; // ~1.0

  // Geometry
  const geometry = new PlaneGeometry(width, height);

  // Material
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    roughness: 0.6,
    metalness: 0.4,
  });

  // Create mesh
  const mesh = new ctx.THREE.Mesh(geometry, material);
  mesh.position.set(x, y, z);
  mesh.rotation.set(rotX, rotY, rotZ);
  mesh.scale.set(scaleX, scaleY, scaleZ);

  // Load texture (async)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = 'srgb';
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // User data with cleanup
  mesh.userData.cleanup = () => {
    material.dispose();
    geometry.dispose();
    const tex = material.map;
    if (tex) tex.dispose();
  };

  mesh.userData.handlers = {};

  return mesh;
};

export default createNode;
